ALTER TABLE public.bank_schedule_config ADD COLUMN last_dispatched_slot text;
CREATE OR REPLACE FUNCTION public.dispatch_bank_schedule() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.bank_schedule_config%ROWTYPE; local_now timestamp:=now() AT TIME ZONE 'Europe/Rome'; slot text:=to_char(local_now,'YYYY-MM-DD HH24:MI'); BEGIN IF to_char(local_now,'HH24:MI') NOT IN ('08:30','15:00') THEN RETURN; END IF; SELECT * INTO c FROM public.bank_schedule_config WHERE id=true AND enabled=true FOR UPDATE; IF NOT FOUND OR c.last_dispatched_slot=slot THEN RETURN; END IF; IF NOT EXISTS(SELECT 1 FROM public.bank_provider_settings WHERE id=true AND provider='open_banking_io' AND costs_verified AND sync_enabled AND monthly_cost_eur IS NOT NULL AND length(trim(commercial_evidence))>0) THEN RETURN; END IF; PERFORM net.http_post(url:=c.endpoint,headers:=jsonb_build_object('Content-Type','application/json','x-bank-schedule-token',c.token),body:='{"action":"scheduled"}'::jsonb,timeout_milliseconds:=10000); UPDATE public.bank_schedule_config SET last_dispatched_slot=slot WHERE id=true; END; $$;
CREATE OR REPLACE FUNCTION public.activate_bank_schedule(_token text,_endpoint text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE job bigint; BEGIN IF coalesce(length(_token),0)<32 OR _endpoint !~ '^https://[a-z0-9]+\.supabase\.co/functions/v1/bank-scheduled-sync$' THEN RAISE EXCEPTION 'Configurazione non valida'; END IF; IF NOT EXISTS(SELECT 1 FROM public.bank_provider_settings WHERE id=true AND provider='open_banking_io' AND costs_verified AND monthly_cost_eur IS NOT NULL AND length(trim(commercial_evidence))>0) THEN RAISE EXCEPTION 'Condizioni non verificate'; END IF; INSERT INTO public.bank_schedule_config(id,token,endpoint,enabled) VALUES(true,_token,_endpoint,true) ON CONFLICT(id) DO UPDATE SET token=excluded.token,endpoint=excluded.endpoint,enabled=true; SELECT cron.schedule('bank-sync-rome','0,30 6,7,13,14 * * *','SELECT public.dispatch_bank_schedule()') INTO job; PERFORM cron.alter_job(job,active:=true); UPDATE public.bank_schedule_config SET job_id=job WHERE id=true; UPDATE public.bank_provider_settings SET sync_enabled=true WHERE id=true; END; $$;
REVOKE ALL ON FUNCTION public.activate_bank_schedule(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.activate_bank_schedule(text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.get_bank_schedule_status() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.can_reconcile_bank(auth.uid()) THEN RAISE EXCEPTION 'Non autorizzato'; END IF; RETURN jsonb_build_object('enabled',coalesce((SELECT c.enabled AND s.sync_enabled FROM public.bank_schedule_config c CROSS JOIN public.bank_provider_settings s WHERE c.id=true AND s.id=true),false),'times',jsonb_build_array('08:30','15:00'),'timezone','Europe/Rome'); END; $$;
REVOKE ALL ON FUNCTION public.get_bank_schedule_status() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_bank_schedule_status() TO authenticated,service_role;